import { describe, expect, test } from 'bun:test';
import { cometToBigint, bigintToComet, nymToShip, sha256, shipToNym } from './mnemonym';
// Generated by Causeway's reference implementation (causeway.patp_to_mnemonym,
// itself vendored from gwbtc/mnemonyms): five live comets plus twenty random.
import vectors from './mnemonym-vectors.json';

const hex = (b: Uint8Array) => Array.from(b, (x) => x.toString(16).padStart(2, '0')).join('');

describe('sha256', () => {
  test('known answers', () => {
    expect(hex(sha256(new Uint8Array()))).toBe(
      'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855',
    );
    expect(hex(sha256(new TextEncoder().encode('abc')))).toBe(
      'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad',
    );
    // two blocks
    expect(
      hex(sha256(new TextEncoder().encode('abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq'))),
    ).toBe('248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1');
  });
});

describe('comet @p codec', () => {
  test('matches Causeway for every vector, both directions', () => {
    for (const v of vectors as Array<{ p: string; n: string; nym: string }>) {
      expect(cometToBigint(v.p)).toBe(BigInt(v.n));
      expect(bigintToComet(BigInt(v.n))).toBe(v.p);
    }
  });
});

describe('mnemonym', () => {
  test('matches Causeway for every vector', () => {
    for (const v of vectors as Array<{ p: string; nym: string }>) {
      expect(shipToNym(v.p)).toBe(v.nym);
      expect(shipToNym(v.p.slice(1))).toBe(v.nym); // without the ~
    }
  });

  test('round-trips back to the @p', () => {
    for (const v of vectors as Array<{ p: string; nym: string }>) {
      expect(nymToShip(v.nym)).toBe(v.p);
      expect(nymToShip(`  ${v.nym.toUpperCase()} `)).toBe(v.p);
    }
  });

  test('a known comet', () => {
    expect(shipToNym('~ponnyd-toblun-libmex-tacsut--lanmus-tilrys-sattes-daplyd')).toBe(
      '.untrained.exhort.admire.decrease.depraved.abstruse.milieu.perform.confer.chastise.defames.kebab',
    );
  });

  test('non-comets have no mnemonym', () => {
    for (const p of ['~zod', '~nec', '~marzod', '~sampel-palnet', '~sampel-palnet-sampel-palnet', 'not-a-ship', '']) {
      expect(shipToNym(p)).toBeNull();
    }
  });

  test('rejects a bad checksum, unknown words, and the untweaked form', () => {
    const good = (vectors as Array<{ nym: string }>)[0].nym;
    const words = good.slice(1).split('.');
    const last = words[words.length - 1];
    const swapped = [...words.slice(0, -1), last === 'abandon' ? 'ability' : 'abandon'];
    expect(nymToShip('.' + swapped.join('.'))).toBeNull();
    expect(nymToShip('.notaword.' + words.slice(1).join('.'))).toBeNull();
    expect(nymToShip('.' + good)).toBeNull(); // '..'
    expect(nymToShip(good.slice(1))).toBeNull(); // no dot
    expect(nymToShip('.')).toBeNull();
  });
});
